// src/components/common/ExcelExporter.ts
/**
* Helper to export tabular data to CSV with UTF-8 BOM for perfect Excel compatibility with Arabic text
*/
function exportToExcel(filename, headers, rows) {
	const processCell = (cell) => {
		if (cell === null || cell === void 0) return "\"\"";
		return `"${cell.toString().replace(/"/g, "\"\"")}"`;
	};
	const csvRows = [];
	csvRows.push(headers.map(processCell).join(","));
	for (const row of rows) csvRows.push(row.map(processCell).join(","));
	const csvContent = "﻿" + csvRows.join("\r\n");
	const cleanFilename = filename.endsWith(".csv") ? filename : `${filename}.csv`;
	if (isNativeCapacitor()) {
		saveAndShareDocument({
			filename: cleanFilename,
			content: csvContent,
			mimeType: "text/csv;charset=utf-8;",
			title: cleanFilename
		}).catch(() => {});
		return;
	}
	const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
	const url = URL.createObjectURL(blob);
	const link = document.createElement("a");
	link.setAttribute("href", url);
	link.setAttribute("download", cleanFilename);
	link.style.visibility = "hidden";
	document.body.appendChild(link);
	link.click();
	document.body.removeChild(link);
	URL.revokeObjectURL(url);
}
