function compressImageFileToDataUrl(file, maxDimension = 640, quality = .76) {
	return new Promise((resolve, reject) => {
		if (!file || !file.type.startsWith("image/")) {
			reject(/* @__PURE__ */ new Error("الملف المختار ليس صورة صالحة"));
			return;
		}
		const reader = new FileReader();
		reader.onerror = () => reject(/* @__PURE__ */ new Error("تعذر قراءة ملف الصورة"));
		reader.onload = () => {
			const img = new Image();
			img.onerror = () => reject(/* @__PURE__ */ new Error("تعذر معالجة الصورة المختارة"));
			img.onload = () => {
				const ratio = Math.min(1, maxDimension / Math.max(img.width || 1, img.height || 1));
				const width = Math.max(1, Math.round(img.width * ratio));
				const height = Math.max(1, Math.round(img.height * ratio));
				const canvas = document.createElement("canvas");
				canvas.width = width;
				canvas.height = height;
				const ctx = canvas.getContext("2d");
				if (!ctx) {
					resolve(String(reader.result || ""));
					return;
				}
				ctx.fillStyle = "#ffffff";
				ctx.fillRect(0, 0, width, height);
				ctx.drawImage(img, 0, 0, width, height);
				resolve(canvas.toDataURL("image/jpeg", quality));
			};
			img.src = String(reader.result || "");
		};
		reader.readAsDataURL(file);
	});
}
